#!/usr/bin/env python3
"""Generate a deterministic project report. Does not grade language proficiency."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
STATE = ROOT / "progress" / "project-state.json"
OUTPUT = ROOT / "docs" / "STATUS.md"
VALID = ("verified", "needs_review", "not_evidenced")

def render(data):
    lines = [
        "# Project status",
        "",
        "> AUTO-GENERATED by `scripts/update_status.py` from `progress/project-state.json`. Do not edit manually.",
        "",
        f"Evidence record last updated: **{data['evidence_updated_at']}**. Checks may be automated or user-reported; this is **not** a Dutch proficiency score.",
        "",
        "A checked item means documented project evidence exists, not that a learning skill is mastered or a workflow has successfully run.",
        "",
    ]
    for phase in data["phases"]:
        counts = {status: sum(t["status"] == status for t in phase["tasks"]) for status in VALID}
        lines.extend([
            f"## {phase['name']}", "",
            f"Verified: **{counts['verified']} / {len(phase['tasks'])}** · Needs review: **{counts['needs_review']}** · Not evidenced: **{counts['not_evidenced']}**",
            "",
        ])
        for task in phase["tasks"]:
            if task["status"] not in VALID:
                raise ValueError(f"Unknown status for {task['id']}: {task['status']}")
            checked = "x" if task["status"] == "verified" else " "
            evidence = f" — evidence: {task['evidence']}" if task.get("evidence") else ""
            lines.append(f"- [{checked}] **{task['id']}** {task['title']} ({task['status']}){evidence}")
        lines.append("")
    lines.extend([
        "## Updating this report", "",
        "1. Validate objective repository evidence with `python scripts/assess_project.py`.",
        "2. Generate this document with `python scripts/update_status.py`.",
        "3. Propose evidence changes in a pull request. Subjective or personal learning progress needs human review and consent.",
        "4. The scheduled GitHub workflow can open a PR for deterministic changes; it does not merge or certify anything.",
        "",
        "No automatic phase promotion or learner obligation is implied.", "",
    ])
    return "\n".join(lines)

def validate(data):
    ids = [task["id"] for phase in data["phases"] for task in phase["tasks"]]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate task identifiers")
    for phase in data["phases"]:
        for task in phase["tasks"]:
            if task["status"] not in VALID:
                raise ValueError(f"Invalid status: {task['id']}")
            if task["status"] == "verified" and not task.get("evidence"):
                raise ValueError(f"Verified task lacks evidence: {task['id']}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="Fail if STATUS.md is outdated")
    args = parser.parse_args()
    data = json.loads(STATE.read_text(encoding="utf-8"))
    validate(data)
    content = render(data)
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text(encoding="utf-8") != content:
            raise SystemExit("STATUS.md is stale. Run python scripts/update_status.py")
        print("STATUS.md is consistent with the evidence ledger.")
    else:
        OUTPUT.write_text(content, encoding="utf-8")
        print("Updated docs/STATUS.md")

if __name__ == "__main__":
    main()
